(function(root){
 'use strict';
 const K=AstraCareerCore;
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const section=t=>`<div class="section-title"><span>✧</span><h3>${t}</h3><span class="line"></span></div>`;
 function result(state,m){
  if(!state.submitted)return '<div class="career-empty"><span>◎</span><h4>用實際行為，補上生日看不到的一面。</h4><p>完成 16 題後才會產生你的 DISC 摘要。這部分依本次回答計分，生日不參與計算。</p></div>';
  const r=K.score(state.answers),label=r.balanced?'多元均衡傾向':r.leaders.map(k=>`${k} ${K.styles[k].name}`).join(' ＋ ');
  return `<div class="career-result-head"><div class="eyebrow">YOUR BEHAVIORAL PREFERENCES</div><h3>${label}</h3><p>${r.balanced?'四項回答相近，請結合情境理解，不強行指定單一類型。':r.leaders.length>1?'最高分並列，保留全部同分風格。':'這是本次自述中較突出的方向，並不代表其他能力較弱。'}</p></div><div class="disc-scores">${Object.entries(K.styles).map(([key,s])=>`<div class="disc-score" style="--disc-color:${s.color}"><div><strong>${key}</strong><span>${s.name}</span><b>${r.averages[key].toFixed(2)} / 5</b></div><div class="disc-track"><span style="width:${r.averages[key]/5*100}%"></span></div><small>${s.focus}</small></div>`).join('')}</div><p class="note-box">各項為 4 題的平均值，並非能力排名、人口百分位或正式測驗常模。</p><div class="career-guides">${(r.balanced?Object.keys(K.styles):r.leaders).map(key=>{const s=K.styles[key];return `<article class="detail-card"><div class="kicker">${key} / ${s.en.toUpperCase()}</div><h3>${s.name}的工作與人際指引</h3><p><b>優勢：</b>${s.strength}</p><p><b>壓力盲點：</b>${s.blind}</p><p><b>工作探索：</b>${s.work}</p><p><b>溝通方式：</b>${s.communicate}</p><p class="career-action"><b>本週練習：</b>${s.practice}</p></article>`;}).join('')}</div>${section('數字主題 × 行為觀察：你的整合提問')}<div class="insight-card"><span class="quote">“</span><div><h3>讓「${e(m.n.tags[0])}」成為能實踐的選擇。</h3><p>數字學的「${e(m.n.title)}」提供動機的象徵；DISC 回答則描述你最近的行為。觀察兩者在哪些場景相近、在哪些場景不同，再以實際經驗修正。不要用其中一項當成另一項必然正確的證明。</p></div></div>`;
 }
 function planSummary(state){return Object.values(state.plan).some(Boolean)?`<article class="detail-card career-plan-summary"><h3>已加入報告的行動紀錄</h3>${[['context','情境與原本的反應'],['action','新的行動'],['review','結果與下次調整']].filter(([key])=>state.plan[key]).map(([key,label])=>`<p><b>${label}：</b><br>${e(state.plan[key])}</p>`).join('')}</article>`:'';}
 function render(state,m,current){
  let html=`<div class="career-banner"><div><div class="eyebrow">LIFE PATH · BEHAVIOR · CHOICE</div><h3>生涯運數 · 天賦、行為與成長</h3><p>結合西方數字學的象徵、DISC 行為風格與日常行為練習，把認識自己帶進工作、人際和選擇。</p></div><span class="career-orbit" aria-hidden="true">◎</span></div><div class="career-context"><span>∞ 數字學：動機提問</span><span>◈ DISC：實際行為自評</span><span>↗ 行為練習：觀察與回饋</span></div><p class="career-disclosure">本頁為 ASTRA 原創整合工具。數字學供象徵性反思；DISC 題目為自編練習，未經標準化驗證，非官方測驗或心理診斷，也不預測職涯結果。</p>${section('01 · 你的生涯主題')}<div class="two-columns"><article class="detail-card"><div class="kicker">NUMEROLOGY / MOTIVATION</div><h3>生命靈數 ${m.calc.number} · ${e(m.n.title)}</h3><p>${e(m.n.desc)}</p><ul><li><b>在意的需求：</b>${e(m.n.motive)}</li><li><b>可發展的天賦：</b>${e(m.n.gift)}。</li><li><b>容易受困之處：</b>${e(m.n.flaw)}</li></ul></article><article class="detail-card"><div class="kicker">ZODIAC / EXPRESSION</div><h3>${e(m.s.name)} · ${e(m.s.role)}</h3><p>${e(m.s.work)}</p><ul><li><b>關係需要：</b>${e(m.s.need)}</li><li><b>人際提醒：</b>${e(m.s.relation)}</li><li><b>成長起點：</b>${e(m.n.practice)}</li></ul></article></div><details><summary>生涯數字的計算與使用方式</summary><div>本頁沿用原生命靈數作為生涯探索的數字主題，未另設新的命運公式：將西曆生日全部數字相加，逐次相加至個位數，過程保留 11、22、33。<div class="calc">${m.calc.digits.join(' + ')} = ${m.calc.steps.join(' → ')}</div>不同流派可能有不同算法。這些描述不等於人格測量；請以實際能力、興趣、環境與經驗探索職涯。</div></details>`;
  if(current.example)return html+`<div class="career-empty" style="margin-top:24px"><span>✧</span><h4>建立你的生日檔案，再開始行為自評。</h4><p>目前為範例。輸入生日後，即可完成 16 題、取得整合建議，並記錄自己的行為改善計畫。</p><button type="button" class="primary-button" id="career-start">輸入我的生日 ↗</button></div>`;
  return html+`${section('02 · DISC 行為風格')}<div id="career-results">${result(state,m)}</div><details id="disc-editor" ${state.submitted?'':'open'}><summary>${state.submitted?'查看或調整作答':'完成 16 題，探索你的行為風格'}</summary><div><p>依最近三個月在日常或工作中的實際表現作答。1 很少、2 偶爾、3 有時、4 經常、5 幾乎總是。每題皆須回答，沒有好壞答案。</p><form id="disc-form" novalidate>${K.questions.map((q,i)=>`<fieldset class="disc-question"><legend><span>${String(i+1).padStart(2,'0')}</span> ${q.text}</legend><div class="disc-options">${[1,2,3,4,5].map(v=>`<label><input type="radio" name="${q.id}" value="${v}" ${state.answers[q.id]===v?'checked':''}><span>${v}<small>${['','很少','偶爾','有時','經常','幾乎總是'][v]}</small></span></label>`).join('')}</div></fieldset>`).join('')}<div class="career-form-actions"><span id="disc-progress" aria-live="polite">${Object.keys(state.answers).length} / 16 題已完成</span><button class="primary-button" type="submit">產生生涯行為報告 ↗</button></div><p class="form-error" role="alert" id="disc-error"></p></form></div></details>${section('03 · 行為心理學練習：情境 → 行動 → 回饋')}<article class="detail-card"><h3>把弱點換成一個可觀察的小行動</h3><p>先記錄引發反應的情境，選一個能做到的新回應，再觀察結果。這是一份自我練習紀錄，不能代替心理評估。</p><div class="path-card"><span class="step-number">01</span><div><h4>辨認觸發點</h4><p>回想一次讓你覺得困難的場合。${e(m.s.trigger)}可能是可供檢視的線索，但不必符合。</p></div></div><div class="path-card"><span class="step-number">02</span><div><h4>試一個替代行為</h4><p>${e(m.n.practice)}如果這不貼近你的情境，請換成自己的小行動。</p></div></div><div class="path-card"><span class="step-number">03</span><div><h4>記錄回饋，而非只評價自己</h4><p>觀察行動後發生了什麼、哪一部分有效、下一次要調整什麼。</p></div></div></article><div id="career-plan-summary">${planSummary(state)}</div><details id="plan-editor" open><summary>我的一週行動紀錄</summary><div><form id="plan-form" novalidate>${[['context','情境與原本的反應',600],['action','新的行動：如果……，我就……',800],['review','實際結果與下次調整',1200]].map(([key,label,max])=>`<label class="career-text-label">${label}<textarea name="${key}" maxlength="${max}" rows="3">${e(state.plan[key])}</textarea></label>`).join('')}<div class="career-form-actions"><button class="primary-button" type="submit">加入這份報告 ↗</button><span id="plan-status" role="status"></span></div><p class="note-box">先按「加入這份報告」，再按上方「收藏／更新收藏」保存在本機；完整報告下載與列印也會包含這份紀錄。</p></form></div></details><details><summary>計分、資料來源與保存方式</summary><div>DISC 四類概念：D 推進、I 連結、S 支持、C 審慎。每類 4 題，各題 1–5 分，分項平均＝該類總分 ÷ 4；同分保留並列。四類總分最高與最低相差不超過 2 時，顯示多元均衡傾向。沒有常模、診斷或精準率主張。<br>作答與紀錄只在本次頁面處理；按「收藏／更新收藏」才儲存至這個瀏覽器，沒有傳送至伺服器。換生日會建立新的檔案。<div class="career-links"><a href="https://www.everythingdisc.com/what-is-disc/" target="_blank" rel="noopener noreferrer">DISC 概念來源 ↗</a></div></div></details>`;
 }
 function bind(state,m,current,refresh,notify,focusBirthday){const $=s=>document.querySelector(s);if($('#career-start')){$('#career-start').onclick=focusBirthday;return;}
  $('#disc-form').addEventListener('change',ev=>{const id=ev.target.name;if(!K.questions.some(q=>q.id===id))return;state.answers[id]=Number(ev.target.value);if(state.submitted){state.submitted=false;$('#career-results').innerHTML='<p class="note-box">答案已更新，請重新產生報告。</p>';}$('#disc-progress').textContent=`${Object.keys(state.answers).length} / 16 題已完成`;$('#disc-error').textContent='';refresh(false);});
  $('#disc-form').onsubmit=ev=>{ev.preventDefault();try{K.score(state.answers);state.submitted=true;refresh();$('#career-results').scrollIntoView({behavior:'smooth',block:'start'});notify('生涯行為報告已完成。');}catch(err){$('#disc-error').textContent=err.message;const q=K.questions.find(q=>!state.answers[q.id]);if(q)document.querySelector(`input[name="${q.id}"]`).focus();}};
  $('#plan-form').onsubmit=ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(ev.target));state.plan=K.normalize({version:2,plan:values}).plan;$('#career-plan-summary').innerHTML=planSummary(state);$('#plan-status').textContent='已加入本次報告，可收藏或下載。';refresh(false);notify('行動紀錄已加入本次報告。');};
 }
 function text(state,m){let out=`\n\n## 10 生涯運數：數字、行為與成長\nASTRA 原創整合工具；數字學為象徵性反思，自編 DISC 概念練習未經標準化驗證。\n\n生涯主題：靈數 ${m.calc.number} ${m.n.title}\n內在需求：${m.n.motive}\n天賦探索：${m.n.gift}\n盲點：${m.n.flaw}\n工作與表達：${m.s.work}\n成長練習：${m.n.practice}\n`;
  if(state.submitted){const r=K.score(state.answers);out+='\nDISC 分項平均（每類 4 題、每題 1–5 分，生日不參與計分）：\n';for(const [key,s] of Object.entries(K.styles))out+=`${key} ${s.name}：${r.averages[key].toFixed(2)} / 5\n`;out+=r.balanced?'四項相近，顯示多元均衡傾向。\n':'最高分風格：'+r.leaders.join(' / ')+'。同分保留並列。\n';for(const key of(r.balanced?Object.keys(K.styles):r.leaders)){const s=K.styles[key];out+=`\n${key} ${s.name}\n優勢：${s.strength}\n盲點：${s.blind}\n工作探索：${s.work}\n溝通：${s.communicate}\n本週練習：${s.practice}\n`;}}else out+='\n尚未完成 DISC 自評，不推定行為風格。\n';
  out+='\n行為反思：記錄情境 → 選擇新行動 → 觀察結果。\n';for(const [key,label] of [['context','情境與原反應'],['action','新的行動'],['review','結果與調整']])if(state.plan[key])out+=`${label}：${state.plan[key]}\n`;return out+'\nDISC 概念：https://www.everythingdisc.com/what-is-disc/\n';}
 root.AstraCareerUI={render,bind,text};
})(globalThis);
